import { parse, stringify } from "./src/index.js";

// Astral Unicode character that is an ID_Continue character
// U+10330 (GOTHIC LETTER AHSA) is an ID_Start character
// U+10331 (GOTHIC LETTER BAIRKAN) is an ID_Continue character
// Let's use characters in the Supplementary Multilingual Plane

// Test with astral ID_Continue character following param name
const testPaths = [
  "/:name-text",        // ASCII hyphen - should quote
  "/:name Vĩnh",        // BMP ID_Continue character (v - works as it's BMP)
  "/:name\U00010331",  // Astral ID_Continue (Gothic letter)
  "/:name\U0001F600",  // Astral but NOT ID_Continue (emoji)
  "/:name\U00013000",  // Astral ID_Continue (Egyptian hieroglyph)
];

// Actually let me construct these properly
const astralIDContinue = "\u{10330}"; // Gothic letter - this is ID_Start
const astralIDContinue2 = "\u{10331}"; // Gothic letter - this is ID_Continue

console.log("Testing astral character: " + astralIDContinue2);
console.log("Code point: U+" + astralIDContinue2.codePointAt(0)!.toString(16));

// String index access on astral characters
console.log("String[0] of astral:", astralIDContinue2[0]);
console.log("String[0] code unit:", astralIDContinue2.charCodeAt(0).toString(16));

// Test the regex
const ID_CONTINUE = /^[$\u200c\u200d\p{ID_Continue}]$/u;
console.log("ID_CONTINUE.test(str[0]):", ID_CONTINUE.test(astralIDContinue2[0]));
console.log("ID_CONTINUE.test(full char):", ID_CONTINUE.test(astralIDContinue2));

// Test parse/stringify round-trip with astral character
const path1 = "/:name" + astralIDContinue2;
console.log("\nParsing path:", path1);
try {
  const tokens = parse(path1);
  console.log("Parsed tokens:", JSON.stringify(tokens, null, 2));
  const str = stringify(tokens);
  console.log("Stringified:", str);
  console.log("Round-trip match:", str === path1);

  // Try to parse the stringified result
  const tokens2 = parse(str);
  const str2 = stringify(tokens2);
  console.log("Second round-trip:", str2 === str);
} catch (e) {
  console.error("Error:", e);
}

