import { parse, stringify } from "./src/index.js";

// Astral ID_Continue character: U+10331 (GOTHIC LETTER BAIRKAN)
const astralIDContinue = "\u{10331}";

// Test where param is followed by text starting with astral ID_Continue
const path1 = "/:name" + astralIDContinue + "suff";
console.log("Parsing path:", path1);
console.log("Path chars:", [...path1].map(c => c.codePointAt(0)?.toString(16)));

try {
  const tokens = parse(path1);
  console.log("Parsed tokens:", JSON.stringify(tokens, null, 2));
  const str = stringify(tokens);
  console.log("Stringified:", str);
  console.log("Round-trip match:", str === path1);

  // What we expect: /:name"𐌱"suff (quoted because followed by astral ID_Continue)
  // What we get: /:name𐌱suff (not quoted)

  // Now try parsing the stringified result
  const tokens2 = parse(str);
  const str2 = stringify(tokens2);
  console.log("Second stringify:", str2);
  console.log("Second round-trip match:", str2 === str);
} catch (e) {
  console.error("Error:", e);
}

console.log("\n---\n");

// Also test with BMP ID_Continue for comparison
const bmpIDContinue = "é"; // U+00E9, ID_Continue
const path2 = "/:name" + bmpIDContinue + "suff";
console.log("Parsing path with BMP char:", path2);
try {
  const tokens = parse(path2);
  console.log("Parsed tokens:", JSON.stringify(tokens, null, 2));
  const str = stringify(tokens);
  console.log("Stringified:", str);
  console.log("Round-trip match:", str === path2);
} catch (e) {
  console.error("Error:", e);
}

