const astralIDContinue = "\u{10331}"; // U+10331, GOTHIC LETTER BAIRKAN

console.log("=== Testing the actual round-trip breakage ===\n");

// Scenario: quoted param name followed by astral ID_Continue text
const path1 = '/"name"' + astralIDContinue + 'rest';
console.log("Original path:", path1);
console.log("Original chars:", [...path1].map(c => "U+" + (c.codePointAt(0)?.toString(16)?.padStart(4, '0'))));

const parsed1 = parse(path1);
console.log("\nParsed tokens:", JSON.stringify(parsed1.tokens, null, 2));

const strung1 = stringify(parsed1);
console.log("\nStringified:", strung1);
console.log("Stringified chars:", [...strung1].map(c => "U+" + (c.codePointAt(0)?.toString(16)?.padStart(4, '0'))));

// Re-parse the stringified version
const reparsed1 = parse(strung1);
console.log("\nReparsed tokens:", JSON.stringify(reparsed1.tokens, null, 2));

const restrung1 = stringify(reparsed1);
console.log("Restrung:", restrung1);

// Check if round-trip is stable
console.log("\nRound-trip stable:", strung1 === restrung1);
console.log("Tokens match:", JSON.stringify(parsed1.tokens) === JSON.stringify(reparsed1.tokens));

// Before the fix:
// - stringify would produce /:name𐌱rest (not quoting)
// - reparse would produce param "name𐌱" (astral char consumed)
// - This is DIFFERENT from original param "name"
//
// After the fix:
// - stringify produces /:name"𐌱"rest (quoting name)
// - reparse produces param "name" + text "𐌱rest"
// - This MATCHES the original tokens

