import { parse, stringify } from "./src/index.js";

const astralIDContinue = "\u{10331}"; // U+10331, GOTHIC LETTER BAIRKAN

console.log("=== Testing the actual round-trip breakage ===\n");

// Using a group to create separate param and text tokens
const path1 = "/{:name}" + astralIDContinue + "rest";
console.log("Original path:", path1);

const parsed1 = parse(path1);
console.log("Parsed tokens:", JSON.stringify(parsed1.tokens, null, 2));

const strung1 = stringify(parsed1);
console.log("Stringified:", strung1);

// Re-parse the stringified version
const reparsed1 = parse(strung1);
console.log("Reparsed tokens:", JSON.stringify(reparsed1.tokens, null, 2));

const restrung1 = stringify(reparsed1);
console.log("Restrung:", restrung1);

console.log("\nRound-trip stable:", strung1 === restrung1);
console.log("Tokens match:", JSON.stringify(parsed1.tokens) === JSON.stringify(reparsed1.tokens));

// Now let me also verify the fix works by reverting and seeing the bug
console.log("\n=== Manual verification ===");

// Manually construct tokens that would trigger the bug
const tokens = [
  { type: "text" as const, value: "/" },
  { type: "param" as const, name: "name" },
  { type: "text" as const, value: astralIDContinue + "rest" },
];

console.log("\nManual tokens:", JSON.stringify(tokens));

import { TokenData } from "./src/index.js";
const manualStr = stringify(new TokenData(tokens));
console.log("Manual stringify:", manualStr);

// Parse the manual stringify
const manualParsed = parse(manualStr);
console.log("Reparsed:", JSON.stringify(manualParsed.tokens));

// Check if param name was preserved
const paramName = (manualParsed.tokens[1] as any).name;
console.log("Param name preserved:", paramName === "name");

