          params: { foo: ["1", "2", "3"], bar: "4", baz: ["5"] },
        },
      },
    ],
  },
  {
    path: "{*path}",
    tests: [
      {
        input: "",
        expected: { path: "", params: {} },
      },
      {
        input: "/",
        expected: { path: "/", params: { path: ["", ""] } },
      },
      {
        input: "/test",
        expected: { path: "/test", params: { path: ["", "test"] } },
      },
      {
        input: "/test/nested",
        expected: {
          path: "/test/nested",
          params: { path: ["", "test", "nested"] },
        },
      },
    ],
  },
  {
    path: "{*path}",
    options: { end: false },
    tests: [
      {
        input: "",
        expected: { path: "", params: {} },
      },
      {
        input: "/",
        expected: { path: "/", params: { path: ["", ""] } },
      },
      {
        input: "/test",
        expected: { path: "/test", params: { path: ["", "test"] } },
      },
      {
        input: "/test/nested",
        expected: {
          path: "/test/nested",
          params: { path: ["", "test", "nested"] },
        },
      },
    ],
  },
  {
    path: "/*path",
    options: { end: false },
    tests: [
      {
        input: "",
        expected: false,
      },
      {
        input: "/",
        expected: false,
      },
      {
        input: "/test",
        expected: { path: "/test", params: { path: ["test"] } },
      },
      {
        input: "/test/nested",
        expected: {
          path: "/test/nested",
          params: { path: ["test", "nested"] },
        },
      },
    ],
  },
  {
    path: "/*path/",
    options: { end: false },
    tests: [
      {
        input: "/foo/bar/",
        expected: { path: "/foo/bar/", params: { path: ["foo", "bar"] } },
      },
      {
        input: "/foo/bar/baz",
        expected: false,
      },
      {
        input: "/foo/bar/baz/",
        expected: {
          path: "/foo/bar/baz/",
          params: { path: ["foo", "bar", "baz"] },
        },
      },
    ],
  },
  {
    path: "/*path.:ext",
    options: { end: false },
    tests: [
      {
        input: "/foo/bar.html",
        expected: {
          path: "/foo/bar.html",
          params: { path: ["foo", "bar"], ext: "html" },
        },
      },
      {
        input: "/foo/bar.html/baz",
        expected: {
          path: "/foo/bar.html",
          params: { path: ["foo", "bar"], ext: "html" },
        },
      },
      {
        input: "/foo/bar.html/baz.html",
        expected: {
          path: "/foo/bar.html/baz.html",
          params: { path: ["foo", "bar.html", "baz"], ext: "html" },
        },
      },
    ],
  },

  /**
   * Longer prefix.
   */
  {
    path: "/:foo{/test/:bar}",
    tests: [
      {
        input: "/route",
        expected: { path: "/route", params: { foo: "route" } },
      },
      {
        input: "/route/test/again",
        expected: {
          path: "/route/test/again",
          params: { foo: "route", bar: "again" },
        },
      },
    ],
  },

  /**
   * Backtracking tests.
   */
  {
    path: "{:foo/}{:bar.}",
    tests: [
      {
        input: "",
        expected: { path: "", params: {} },
      },
      {
        input: "test/",
        expected: {
          path: "test/",
          params: { foo: "test" },
        },
      },
      {
        input: "a/b.",
        expected: { path: "a/b.", params: { foo: "a", bar: "b" } },
      },
    ],
  },
  {
    path: "/abc{abc:foo}",
    tests: [
      {
        input: "/abc",
        expected: { path: "/abc", params: {} },
      },
      {
        input: "/abcabc",
        expected: false,
      },
      {
        input: "/abcabc123",
        expected: { path: "/abcabc123", params: { foo: "123" } },
      },
      {
        input: "/abcabcabc123",
        expected: {
          path: "/abcabcabc123",
