import { parse, stringify, TokenData } from "./src/index.js";

let passed = 0;
let failed = 0;

function test(name: string, actual: string, expected: string) {
  const pass = actual === expected;
  if (pass) {
    passed++;
    console.log(`✓ ${name}`);
  } else {
    failed++;
    console.log(`✗ ${name}`);
    console.log(`  Expected: ${JSON.stringify(expected)}`);
    console.log(`  Actual:   ${JSON.stringify(actual)}`);
  }
}

// Astral ID_Continue characters
const astralIDContinueChars = [
  { char: "\u{1D6FC}", name: "MATHEMATICAL ITALIC SMALL ALPHA" },
  { char: "\u{10331}", name: "GOTHIC LETTER BAIRKAN" },
  { char: "\u{13000}", name: "EGYPTIAN HIEROGLYPH A001" },
  { char: "\u{1F100}", name: "LATIN EPIGRAPHIC LETTER SIDEWAYS U" },
];

console.log("=== Astral ID_Continue characters should trigger quoting ===\n");

for (const { char, name } of astralIDContinueChars) {
  const data = new TokenData([
    { type: "text", value: "/" },
    { type: "param", name: "test" },
    { type: "text", value: char },
  ]);
  const result = stringify(data);
  test(`Param + ${name} (U+${char.codePointAt(0)?.toString(16).toUpperCase()})`, result, `/:test"${char}"`);
}

console.log("\n=== Non-ID_Continue astral characters should NOT trigger quoting ===\n");

const nonIDContinueChars = [
  { char: "\u{1F600}", name: "GRINNING FACE" },
  { char: "\u{20000}", name: "CJK UNIFIED IDEOGRAPH-20000" },  // CJK might be ID_Continue though
  { char: "\u{FFFD}", name: "REPLACEMENT CHARACTER" },
];

for (const { char, name } of nonIDContinueChars) {
  const data = new TokenData([
    { type: "text", value: "/" },
    { type: "param", name: "test" },
    { type: "text", value: char },
  ]);
  const result = stringify(data);
  // For non-ID_Continue, the name should NOT be quoted
  test(`Param + ${name} (U+${char.codePointAt(0)?.toString(16).toUpperCase()})`, result, `/:test${char}`);
}

console.log("\n=== BMP ID_Continue characters should still trigger quoting ===\n");

const bmpIDContinueChars = [
  { char: "\u00E9", name: "LATIN SMALL LETTER E WITH ACUTE" },
  { char: "\u03B1", name: "GREEK SMALL LETTER ALPHA" },
  { char: "\u3042", name: "HIRAGANA LETTER A" },
];

for (const { char, name } of bmpIDContinueChars) {
  const data = new TokenData([
    { type: "text", value: "/" },
    { type: "param", name: "test" },
    { type: "text", value: char },
  ]);
  const result = stringify(data);
  test(`Param + ${name} (U+${char.codePointAt(0)?.toString(16).toUpperCase()})`, result, `/:test"${char}"`);
}

console.log("\n=== Wildcard params should also be quoted ===\n");

for (const { char, name } of astralIDContinueChars) {
  const data = new TokenData([
    { type: "text", value: "/" },
    { type: "wildcard", name: "splat" },
    { type: "text", value: char },
  ]);
  const result = stringify(data);
  test(`Wildcard + ${name}`, result, `/*splat"${char}"`);
}

console.log("\n=== Round-trip stability ===\n");

for (const { char, name } of astralIDContinueChars) {
  // Parse a path with quoted param followed by astral ID_Continue
  const path = `/:test"${char}"suffix`;
  const parsed = parse(path);
  const strung = stringify(parsed);
  const reparsed = parse(strung);
  const restrung = stringify(reparsed);
  test(`Round-trip: ${name}`, restrung, strung);
}

console.log(`\n=== Results: ${passed} passed, ${failed} failed ===`);
process.exit(failed > 0 ? 1 : 0);

