let passed = 0;
let failed = 0;

function test(name: string, actual: string, expected: string) {
  const pass = actual === expected;
  if (pass) {
    passed++;
    console.log(`✓ ${name}`);
  } else {
    failed++;
    console.log(`✗ ${name}`);
    console.log(`  Expected: ${[...expected].map(c => "U+" + (c.codePointAt(0)?.toString(16)?.padStart(4, '0'))).join(' ')}`);
    console.log(`  Actual:   ${[...actual].map(c => "U+" + (c.codePointAt(0)?.toString(16)?.padStart(4, '0'))).join(' ')}`);
  }
}

// Astral ID_Continue characters
const astralIDContinueChars = [
  { char: "\u{1D6FC}", name: "MATHEMATICAL ITALIC SMALL ALPHA" },
  { char: "\u{10331}", name: "GOTHIC LETTER BAIRKAN" },
  { char: "\u{13000}", name: "EGYPTIAN HIEROGLYPH A001" },
  { char: "\u{1F100}", name: "LATIN EPIGRAPHIC LETTER SIDEWAYS U" },
];

console.log("=== Astral ID_Continue characters should trigger quoting ===\n");

for (const { char, name } of astralIDContinueChars) {
  const data = new TokenData([
    { type: "text", value: "/" },
    { type: "param", name: "test" },
    { type: "text", value: char + "suffix" },
  ]);
